        BlockPos blockpos = playerentity.blockPosition();
        BlockPos blockpos2 = this.func_221244_a(blockpos, 84);
        if (blockpos2 != null && this.func_226559_a_(blockpos2) && blockpos2.distSqr(blockpos) > 225) {
